export interface ModelEntry {
  id: string
  name: string
  description: string
  sogUrl: string
  thumbnail?: string
  tags: string[]
  splatCount?: number
}

export type EditMode = 'view' | 'select' | 'move' | 'delete' | 'annotate' | 'edit-annotation'

export type AnnotationType = 'point' | 'area' | 'path' | 'note'

export interface AnnotationPoint {
  id: string
  position: { x: number; y: number; z: number }
  label: string
  description: string
  color: number
  type: AnnotationType
  fontSize: number
  createdAt: number
  updatedAt: number
}

export const ANNOTATION_STORAGE_KEY = 'splatshow-annotations'

export function loadAnnotations(): AnnotationPoint[] {
  try {
    const raw = localStorage.getItem(ANNOTATION_STORAGE_KEY)
    if (!raw) return []
    const parsed = JSON.parse(raw)
    if (!Array.isArray(parsed)) return []
    return parsed as AnnotationPoint[]
  } catch {
    return []
  }
}

export function saveAnnotations(annotations: AnnotationPoint[]): void {
  try {
    localStorage.setItem(ANNOTATION_STORAGE_KEY, JSON.stringify(annotations))
  } catch {
    console.warn('[Annotations] Failed to save to localStorage')
  }
}

export interface ViewerState {
  isLoading: boolean
  progress: number
  error: string | null
  splatCount: number
  fps: number
  isWireframe: boolean
  isFullscreen: boolean
  showInfoPanel: boolean
  editMode: EditMode
  selectedCount: number
}

export const DEFAULT_MODEL_URL = 'https://cdn.jsdelivr.net/gh/sky12341455/splatshow-viewer@gh-pages/assets/models/point_cloud_30000.spz'
export const DEFAULT_MODEL_NAME = 'Point Cloud 30000 (SPZ)'