import { useState, useEffect } from 'react'
import { Save, X, Move3D, Type, AlignLeft, Tag } from 'lucide-react'
import type { AnnotationPoint, AnnotationType } from '../../types'

interface AnnotationEditPanelProps {
  annotation: AnnotationPoint
  currentPosition: { x: number; y: number; z: number }
  isDragging: boolean
  onSave: (updated: Partial<AnnotationPoint>) => void
  onCancel: () => void
}

const ANNOTATION_TYPES: { value: AnnotationType; label: string; color: string }[] = [
  { value: 'point', label: '点位', color: '#00D2FF' },
  { value: 'area', label: '区域', color: '#FFD700' },
  { value: 'path', label: '路径', color: '#26de81' },
  { value: 'note', label: '备注', color: '#a55eea' },
]

export function AnnotationEditPanel({
  annotation,
  currentPosition,
  isDragging,
  onSave,
  onCancel,
}: AnnotationEditPanelProps) {
  const [label, setLabel] = useState(annotation.label)
  const [description, setDescription] = useState(annotation.description)
  const [type, setType] = useState<AnnotationType>(annotation.type)
  const [fontSize, setFontSize] = useState(annotation.fontSize)

  useEffect(() => {
    setLabel(annotation.label)
    setDescription(annotation.description)
    setType(annotation.type)
    setFontSize(annotation.fontSize)
  }, [annotation.id])

  const handleSave = () => {
    onSave({
      label: label.trim() || annotation.label,
      description: description.trim(),
      type,
      fontSize,
      position: { ...currentPosition },
      updatedAt: Date.now(),
    })
  }

  const pos = currentPosition || annotation.position

  return (
    <div className="fixed right-4 top-20 z-30 w-72 rounded-xl bg-[#0a0a0f]/95 backdrop-blur-xl border border-[#00D2FF]/20 shadow-xl shadow-black/40 animate-in slide-in-from-right-4">
      <div className="px-5 py-4 border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center gap-2">
          <PencilIcon />
          <span className="text-xs font-medium text-white/80 tracking-wide">编辑注解</span>
        </div>
        <button
          onClick={onCancel}
          className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-white/10 text-white/30 hover:text-white/60 transition-colors"
          title="取消编辑"
        >
          <X className="w-3.5 h-3.5" />
        </button>
      </div>

      <div className="p-5 space-y-4 max-h-[calc(100vh-220px)] overflow-y-auto custom-scrollbar">
        <div className="space-y-1.5">
          <label className="flex items-center gap-1.5 text-[10px] tracking-widest uppercase text-white/30">
            <Type className="w-3 h-3" />
            标题
          </label>
          <input
            type="text"
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            maxLength={50}
            placeholder="输入注解标题…"
            className="w-full px-3 py-2 rounded-lg bg-white/[0.04] border border-white/8 text-sm text-white/90 outline-none placeholder:text-white/15 focus:border-[#00D2FF]/30 focus:bg-white/[0.06] transition-all"
            autoFocus
          />
        </div>

        <div className="space-y-1.5">
          <label className="flex items-center gap-1.5 text-[10px] tracking-widest uppercase text-white/30">
            <AlignLeft className="w-3 h-3" />
            描述
          </label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            maxLength={500}
            rows={3}
            placeholder="输入详细描述（可选）…"
            className="w-full px-3 py-2 rounded-lg bg-white/[0.04] border border-white/8 text-sm text-white/90 outline-none placeholder:text-white/15 focus:border-[#00D2FF]/30 focus:bg-white/[0.06] transition-all resize-none"
          />
        </div>

        <div className="space-y-1.5">
          <label className="flex items-center gap-1.5 text-[10px] tracking-widest uppercase text-white/30">
            <Tag className="w-3 h-3" />
            类型
          </label>
          <div className="grid grid-cols-2 gap-1.5">
            {ANNOTATION_TYPES.map((t) => (
              <button
                key={t.value}
                onClick={() => setType(t.value)}
                className={`px-3 py-1.5 rounded-lg text-[11px] transition-all ${
                  type === t.value
                    ? `border shadow-sm`
                    : 'bg-white/[0.03] border-white/6 text-white/40 hover:bg-white/[0.06]'
                }`}
                style={
                  type === t.value
                    ? { backgroundColor: t.color + '15', borderColor: t.color + '40', color: t.color }
                    : undefined
                }
              >
                {t.label}
              </button>
            ))}
          </div>
        </div>

        <div className="space-y-1.5">
          <label className="flex items-center gap-1.5 text-[10px] tracking-widest uppercase text-white/30">
            <Move3D className="w-3 h-3" />
            位置坐标
            {isDragging && (
              <span className="ml-auto text-[9px] px-1.5 py-0.5 rounded bg-[#FFD700]/15 text-[#FFD700] animate-pulse">
                拖动中…
              </span>
            )}
          </label>
          <div className="grid grid-cols-3 gap-1.5">
            {(['x', 'y', 'z'] as const).map((axis) => (
              <div key={axis} className="flex flex-col gap-0.5">
                <span className={`text-[9px] uppercase tracking-wider ${axis === 'x' ? 'text-red-400/60' : axis === 'y' ? 'text-green-400/60' : 'text-blue-400/60'}`}>
                  {axis}
                </span>
                <div className="px-2 py-1.5 rounded-md bg-white/[0.03] border border-white/6 text-[11px] tabular-nums text-white/50 font-mono">
                  {pos[axis].toFixed(3)}
                </div>
              </div>
            ))}
          </div>
          <p className="text-[9px] text-white/15">拖动 3D 坐标轴可移动注点位置</p>
        </div>
      </div>

      <div className="px-5 py-4 border-t border-white/5 flex items-center gap-2">
        <button
          onClick={onCancel}
          className="flex-1 px-4 py-2 rounded-lg bg-white/[0.04] border border-white/8 text-xs text-white/40 hover:bg-white/[0.08] hover:text-white/60 transition-colors"
        >
          取消
        </button>
        <button
          onClick={handleSave}
          className="flex-1 px-4 py-2 rounded-lg bg-[#00D2FF]/15 border border-[#00D2FF]/25 text-xs text-[#00D2FF] hover:bg-[#00D2FF]/25 hover:border-[#00D2FF]/40 transition-colors font-medium flex items-center justify-center gap-1.5"
        >
          <Save className="w-3.5 h-3.5" />
          保存更改
        </button>
      </div>
    </div>
  )
}

function PencilIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-[#00D2FF]/70">
      <path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z" />
      <path d="m15 5 4 4" />
    </svg>
  )
}
