import { MapPin, Trash2, Eye, Pencil } from 'lucide-react'
import type { AnnotationPoint } from '../../types'

interface AnnotationListPanelProps {
  annotations: AnnotationPoint[]
  editingId: string | null
  onSelect: (annotation: AnnotationPoint) => void
  onDelete: (id: string) => void
  onFlyTo?: (position: AnnotationPoint['position']) => void
}

const TYPE_LABELS: Record<string, string> = {
  point: '点位',
  area: '区域',
  path: '路径',
  note: '备注',
}

export function AnnotationListPanel({
  annotations,
  editingId,
  onSelect,
  onDelete,
  onFlyTo,
}: AnnotationListPanelProps) {
  if (annotations.length === 0) return null

  return (
    <div className="fixed left-4 top-20 z-30 w-56 max-h-[calc(100vh-140px)] flex flex-col rounded-xl bg-[#0a0a0f]/90 backdrop-blur-xl border border-white/5 shadow-xl shadow-black/30">
      <div className="px-4 py-3 border-b border-white/5 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-2">
          <MapPin className="w-3.5 h-3.5 text-[#00D2FF]/60" />
          <span className="text-[11px] tracking-widest uppercase text-white/40">
            注解列表
          </span>
        </div>
        <span className="text-[10px] tabular-nums text-white/20 bg-white/5 px-1.5 py-0.5 rounded">
          {annotations.length}
        </span>
      </div>

      <div className="flex-1 overflow-y-auto p-2 space-y-0.5 custom-scrollbar">
        {annotations.map((ann) => {
          const isEditing = editingId === ann.id
          const colorHex = '#' + ann.color.toString(16).padStart(6, '0')

          return (
            <div
              key={ann.id}
              onClick={() => onSelect(ann)}
              className={`group relative flex items-center gap-2.5 px-3 py-2.5 rounded-lg cursor-pointer transition-all ${
                isEditing
                  ? 'bg-[#00D2FF]/10 border border-[#00D2FF]/25'
                  : 'hover:bg-white/[0.04] border border-transparent'
              }`}
            >
              <span
                className="w-2.5 h-2.5 rounded-full flex-shrink-0 ring-1 ring-white/10"
                style={{ backgroundColor: colorHex }}
              />

              <div className="flex-1 min-w-0">
                <p className={`text-xs truncate ${isEditing ? 'text-[#00D2FF] font-medium' : 'text-white/70'}`}>
                  {ann.label || '未命名注点'}
                </p>
                <p className="text-[10px] text-white/20 truncate mt-0.5">
                  {TYPE_LABELS[ann.type] || '点位'}
                  {' · '}
                  ({ann.position.x.toFixed(1)}, {ann.position.y.toFixed(1)}, {ann.position.z.toFixed(1)})
                </p>
              </div>

              <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity shrink-0">
                {onFlyTo && (
                  <button
                    onClick={(e) => {
                      e.stopPropagation()
                      onFlyTo(ann.position)
                    }}
                    className="w-6 h-6 flex items-center justify-center rounded-md hover:bg-white/10 text-white/30 hover:text-white/60 transition-colors"
                    title="定位到该点"
                  >
                    <Eye className="w-3 h-3" />
                  </button>
                )}
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    if (isEditing) onSelect(ann)
                    else onSelect(ann)
                  }}
                  className="w-6 h-6 flex items-center justify-center rounded-md hover:bg-white/10 text-white/30 hover:text-[#00D2FF] transition-colors"
                  title={isEditing ? '编辑中' : '编辑'}
                >
                  <Pencil className="w-3 h-3" />
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation()
                    onDelete(ann.id)
                  }}
                  className="w-6 h-6 flex items-center justify-center rounded-md hover:bg-red-500/10 text-white/20 hover:text-red-400 transition-colors"
                  title="删除"
                >
                  <Trash2 className="w-3 h-3" />
                </button>
              </div>

              {isEditing && (
                <div className="absolute right-2 top-1/2 -translate-y-1/2">
                  <span className="text-[9px] px-1.5 py-0.5 rounded bg-[#00D2FF]/15 text-[#00D2FF] tracking-wider">
                    编辑中
                  </span>
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}
